        style = "display: flex;", id = "chainHolder",
        tags$div(
          style = "padding: 5px;",
          tags$label("Sequence of")
        ),
        tags$div(
          style = "width:100px;",
          selectizeInput(ns("selectedChain"), label = NULL, r$chainname, selected = "element", width = "100%")
        )
      ))
