    .style('display', 'flex')
    .style('flex-direction', 'column')
    .style('color', (d, i) => {
    if(d.unique == true){
    return("black")
  } else {
    return("red")
  }
    })
    .on('mouseenter', (d, i) => {
      aaMouseover(d, i);
        if (isMouseDown) {
          aaSelStop = d.Nr
          aaRange(aaSelStart, aaSelStop).forEach(function(i) {
            sequenceContainer.select(`#aa-${i}`)
              .style('background-color', 'rgb(255,102,153)');
          })
        }
      // let aaBackground = sequenceContainer.select(`#aa-${d.Nr}`).style('background-color')
      //   if (aaBackground == 'rgba(0, 0, 0, 0)') {
      // sequenceContainer.select(`#aa-${d.Nr}`)
      //   .style('background-color', 'red');
      // } else {
      //   sequenceContainer.select(`#aa-${d.Nr}`)
      //     .style('background-color', 'rgba(0, 0, 0, 0)');
      // }
    })
    .on('mouseout', (d,i) => {
      aaMouseout(d, i);
      if (isMouseDown) {
        aaSelStop = d.Nr
        aaRange(aaSelStart, aaSelStop).forEach(function(i) {
          sequenceContainer.select(`#aa-${i}`)
            .style('background-color', 'rgba(0, 0, 0, 0)');
        })
      }
    })
   .on('mousedown', (d,i) => {
     isMouseDown = true
     aaSelStart = d.Nr
     aaSelStop = null
    })
    .on('mouseup', (d, i) => {
          isMouseDown = false
          sequenceContainer.selectAll('.aaContainer')
            .style('background-color', 'rgba(0, 0, 0, 0)');

          if (aaSelStop == null) {
            let excists = aaSel.includes(aaSelStart)
            if (excists == false) {
              aaSel.push(aaSelStart);
            } else {
              aaSel = aaSel.filter(function(value, index, arr) {
                return value !== aaSelStart
              });
            }
          } else {
            aaRange(aaSelStart, aaSelStop).forEach(function(i) {
              let excists = aaSel.includes(i)
              if (excists == false) {
                aaSel.push(i);
              } else {
                aaSel = aaSel.filter(function(value, index, arr) {
                  return value !== i
                });
              }
            });
          }
          setTimeout(function() {

            aaSel.forEach(function(i) {
              sequenceContainer.select(`#aa-${i}`)
                .style('background-color', 'rgb(51, 255, 25)');
            })
            aaSelStop = null
            aaSelStart = null
            aaHighlight(options.seqPositions);
          }, 10);
    })
    function aaHighlight(positions) {

    //Convert to array if input has only one position
    if (!Array.isArray(positions)) {
      positions = [positions]
    }

    if (positions != null) {
      for (var i = 0; i < positions.length; i++) {
        sequenceContainer.select(`#aa-${positions[i]}`)
          .style('background-color', 'rgb(51, 255, 25)');
      }
      // positions.forEach(function(i) {
      //   sequenceContainer.select(`#aa-${i}`)
      //     .style('background-color', 'rgb(51, 255, 25)');
      // })
      Shiny.setInputValue(
        "aa_clicked",
        aaSel, {
          priority: "event"
        }
      );
    }
  }

  aaHighlight(options.seqPositions);
  });

/* ============================================================== */
/* Global layout                                                  */
/* ============================================================== */

body {
  overflow-x: hidden;
}

.sidebar {
  height: 90dvh;
  overflow-y: auto;
}

.content {
  padding: 10px 0 0 0;
}

.content-wrapper {
  background-color: black;
}

/* ============================================================== */
/* Boxes — kept minimal to preserve the dark viewer aesthetic     */
/* ============================================================== */

.box {
  margin: 0;
  border: 0;
  box-shadow: 0 0 0;
}

.box.box-solid.box-primary > .box-header {
  background-color: black;
}

.box.box-solid.box-primary {
  border-color: #fff;
}

/* ============================================================== */
/* Sidebar items                                                  */
/* ============================================================== */

.treeview-menu {
  padding-bottom: 15px;
}

.btn-link {
  font-weight: 700;
}

/* ============================================================== */
/* Sequence output bar                                            */
/* ============================================================== */

#sequence {
  margin: 0;
  padding: 0;
}

#sequence .btn-primary {
  background-color: black;
  margin: 0;
  padding: 5px;
}

/* ============================================================== */
/* NGL viewer                                                     */
/* ============================================================== */

/* Class-based — independent of module instance ids. The actual height
   is set inline by NGLVieweROutput(height = "91dvh") in R; this rule
   only enforces the mobile minimum required for legible WebGL. */
.NGLVieweR.html-widget {
  min-height: 250px;
}

/* ============================================================== */
/* Floating label controls box                                    */
/* ============================================================== */

#labelcontrols_ui_1-labelBox .btn-primary {
  background-color: black;
  margin: 0;
  padding: 5px;
}

.hideBox {
  visibility: hidden;
}

/* ============================================================== */
/* Tablet (≤768px): tighten layout, ensure 44px touch targets     */
/* ============================================================== */

@media (max-width: 768px) {
  .sidebar {
    height: auto;
    max-height: 80dvh;
  }

  .content,
  .content-wrapper {
    padding: 8px 0 0 0;
  }

  .btn,
  .btn-link,
  .form-control,
  .selectize-input,
  .colourpicker-panel input,
  input[type="text"],
  input[type="number"] {
    min-height: 44px;
  }

  .treeview-menu > li > a,
  .sidebar-menu > li > a {
    padding-top: 12px;
    padding-bottom: 12px;
  }
}

/* ============================================================== */
/* Phone (≤480px): tighter padding, slightly smaller titles       */
/* ============================================================== */

@media (max-width: 480px) {
  .sidebar {
    max-height: 60dvh;
  }

  .box-title,
  .box-header h3 {
    font-size: 14px;
  }

  .content,
  .content-wrapper {
    padding: 4px 0 0 0;
  }
}
